-- Frozen initial schema. Existing tables are preserved.
CREATE TABLE IF NOT EXISTS "artists" ("id"  SERIAL , "name" VARCHAR(500) NOT NULL UNIQUE, "createdAt" TIMESTAMP WITH TIME ZONE NOT NULL, "updatedAt" TIMESTAMP WITH TIME ZONE NOT NULL, PRIMARY KEY ("id"));
CREATE TABLE IF NOT EXISTS "albums" ("id"  SERIAL , "name" VARCHAR(500) NOT NULL, "artistId" INTEGER NOT NULL REFERENCES "artists" ("id") ON DELETE NO ACTION ON UPDATE CASCADE, "createdAt" TIMESTAMP WITH TIME ZONE NOT NULL, "updatedAt" TIMESTAMP WITH TIME ZONE NOT NULL, PRIMARY KEY ("id"));
CREATE UNIQUE INDEX IF NOT EXISTS "albums_name_artist_id" ON "albums" ("name", "artistId");
CREATE TABLE IF NOT EXISTS "tracks" ("id"  SERIAL , "name" VARCHAR(500) NOT NULL, "albumId" INTEGER NOT NULL REFERENCES "albums" ("id") ON DELETE NO ACTION ON UPDATE CASCADE, "uri" TEXT, "duration" INTEGER, "createdAt" TIMESTAMP WITH TIME ZONE NOT NULL, "updatedAt" TIMESTAMP WITH TIME ZONE NOT NULL, PRIMARY KEY ("id"));
CREATE UNIQUE INDEX IF NOT EXISTS "tracks_name_album_id" ON "tracks" ("name", "albumId");
CREATE INDEX IF NOT EXISTS "tracks_uri" ON "tracks" ("uri");
CREATE TABLE IF NOT EXISTS "profiles" ("id"  SERIAL , "name" VARCHAR(255) NOT NULL UNIQUE, "username" VARCHAR(255), "lastImport" TIMESTAMP WITH TIME ZONE, "statistics" JSONB NOT NULL DEFAULT '{"totalPlays":0,"totalMinutes":0,"uniqueTracks":0,"uniqueArtists":0,"uniqueAlbums":0,"totalPodcastPlays":0,"totalAudiobookPlays":0,"uniqueShows":0,"uniqueEpisodes":0,"uniqueAudiobooks":0}', "createdAt" TIMESTAMP WITH TIME ZONE NOT NULL, "updatedAt" TIMESTAMP WITH TIME ZONE NOT NULL, PRIMARY KEY ("id"));
CREATE TABLE IF NOT EXISTS "plays" ("id"  SERIAL , "trackId" INTEGER NOT NULL REFERENCES "tracks" ("id") ON DELETE NO ACTION ON UPDATE CASCADE, "profileId" INTEGER REFERENCES "profiles" ("id") ON DELETE SET NULL ON UPDATE CASCADE, "timestamp" TIMESTAMP WITH TIME ZONE NOT NULL, "msPlayed" INTEGER NOT NULL, "username" VARCHAR(255), "platform" VARCHAR(255), "country" VARCHAR(2), "ipAddr" VARCHAR(45), "userAgent" TEXT, "reasonStart" VARCHAR(100), "reasonEnd" VARCHAR(100), "shuffle" BOOLEAN, "skipped" BOOLEAN, "offline" BOOLEAN, "offlineTimestamp" TIMESTAMP WITH TIME ZONE, "incognitoMode" BOOLEAN, "createdAt" TIMESTAMP WITH TIME ZONE NOT NULL, "updatedAt" TIMESTAMP WITH TIME ZONE NOT NULL, PRIMARY KEY ("id"));
CREATE INDEX IF NOT EXISTS "plays_track_id_timestamp" ON "plays" ("trackId", "timestamp");
CREATE INDEX IF NOT EXISTS "plays_timestamp_country" ON "plays" ("timestamp", "country");
CREATE INDEX IF NOT EXISTS "plays_timestamp_platform" ON "plays" ("timestamp", "platform");
CREATE INDEX IF NOT EXISTS "plays_profile_id_timestamp" ON "plays" ("profileId", "timestamp");
CREATE INDEX IF NOT EXISTS "plays_profile_id_track_id" ON "plays" ("profileId", "trackId");
CREATE INDEX IF NOT EXISTS "plays_timestamp" ON "plays" ("timestamp");
CREATE INDEX IF NOT EXISTS "plays_ms_played" ON "plays" ("msPlayed");
CREATE INDEX IF NOT EXISTS "plays_platform" ON "plays" ("platform");
CREATE INDEX IF NOT EXISTS "plays_country" ON "plays" ("country");
CREATE INDEX IF NOT EXISTS "plays_shuffle" ON "plays" ("shuffle");
CREATE INDEX IF NOT EXISTS "plays_skipped" ON "plays" ("skipped");
CREATE INDEX IF NOT EXISTS "plays_offline" ON "plays" ("offline");
CREATE INDEX IF NOT EXISTS "plays_incognito_mode" ON "plays" ("incognitoMode");
CREATE TABLE IF NOT EXISTS "artist_stats" ("id"  SERIAL , "profileId" INTEGER NOT NULL REFERENCES "profiles" ("id") ON DELETE NO ACTION ON UPDATE CASCADE, "artistId" INTEGER NOT NULL REFERENCES "artists" ("id") ON DELETE NO ACTION ON UPDATE CASCADE, "artistName" VARCHAR(500) NOT NULL, "totalPlays" INTEGER NOT NULL DEFAULT 0, "totalMinutes" DECIMAL(10,2) NOT NULL DEFAULT 0, "uniqueTracks" INTEGER NOT NULL DEFAULT 0, "uniqueAlbums" INTEGER NOT NULL DEFAULT 0, "firstPlayDate" TIMESTAMP WITH TIME ZONE, "lastPlayDate" TIMESTAMP WITH TIME ZONE, "topTrack" JSONB, "createdAt" TIMESTAMP WITH TIME ZONE NOT NULL, "updatedAt" TIMESTAMP WITH TIME ZONE NOT NULL, PRIMARY KEY ("id"));
CREATE UNIQUE INDEX IF NOT EXISTS "artist_stats_profile_id_artist_id" ON "artist_stats" ("profileId", "artistId");
CREATE INDEX IF NOT EXISTS "artist_stats_profile_id_total_plays" ON "artist_stats" ("profileId", "totalPlays");
CREATE INDEX IF NOT EXISTS "artist_stats_profile_id_total_minutes" ON "artist_stats" ("profileId", "totalMinutes");
CREATE TABLE IF NOT EXISTS "country_stats" ("id"  SERIAL , "profileId" INTEGER NOT NULL REFERENCES "profiles" ("id") ON DELETE NO ACTION ON UPDATE CASCADE, "country" VARCHAR(2) NOT NULL, "totalPlays" INTEGER NOT NULL DEFAULT 0, "totalMinutes" DECIMAL(10,2) NOT NULL DEFAULT 0, "percentage" DECIMAL(5,2) NOT NULL DEFAULT 0, "uniqueTracks" INTEGER NOT NULL DEFAULT 0, "uniqueArtists" INTEGER NOT NULL DEFAULT 0, "topArtist" JSONB, "createdAt" TIMESTAMP WITH TIME ZONE NOT NULL, "updatedAt" TIMESTAMP WITH TIME ZONE NOT NULL, PRIMARY KEY ("id"));
CREATE UNIQUE INDEX IF NOT EXISTS "country_stats_profile_id_country" ON "country_stats" ("profileId", "country");
CREATE INDEX IF NOT EXISTS "country_stats_profile_id_total_plays" ON "country_stats" ("profileId", "totalPlays");
CREATE INDEX IF NOT EXISTS "country_stats_total_plays" ON "country_stats" ("totalPlays");
CREATE TABLE IF NOT EXISTS "daily_stats" ("id"   SERIAL , "profileId" INTEGER NOT NULL REFERENCES "profiles" ("id") ON DELETE NO ACTION ON UPDATE CASCADE, "date" DATE NOT NULL, "totalPlays" INTEGER DEFAULT 0, "totalMinutes" INTEGER DEFAULT 0, "uniqueTracks" INTEGER DEFAULT 0, "uniqueArtists" INTEGER DEFAULT 0, "topArtist" JSONB, "topTrack" JSONB, "createdAt" TIMESTAMP WITH TIME ZONE NOT NULL, "updatedAt" TIMESTAMP WITH TIME ZONE NOT NULL, PRIMARY KEY ("id"));
CREATE UNIQUE INDEX IF NOT EXISTS "daily_stats_profile_id_date" ON "daily_stats" ("profileId", "date");
CREATE INDEX IF NOT EXISTS "daily_stats_date_profile_id" ON "daily_stats" ("date", "profileId");
CREATE TABLE IF NOT EXISTS "yearly_stats" ("id"   SERIAL , "profileId" INTEGER NOT NULL REFERENCES "profiles" ("id") ON DELETE NO ACTION ON UPDATE CASCADE, "year" INTEGER NOT NULL, "totalPlays" INTEGER DEFAULT 0, "totalMinutes" INTEGER DEFAULT 0, "uniqueTracks" INTEGER DEFAULT 0, "uniqueArtists" INTEGER DEFAULT 0, "uniqueAlbums" INTEGER DEFAULT 0, "topArtist" JSONB, "topTrack" JSONB, "monthlyBreakdown" JSONB, "createdAt" TIMESTAMP WITH TIME ZONE NOT NULL, "updatedAt" TIMESTAMP WITH TIME ZONE NOT NULL, PRIMARY KEY ("id"));
CREATE UNIQUE INDEX IF NOT EXISTS "yearly_stats_profile_id_year" ON "yearly_stats" ("profileId", "year");
CREATE INDEX IF NOT EXISTS "yearly_stats_year_profile_id" ON "yearly_stats" ("year", "profileId");
CREATE TABLE IF NOT EXISTS "shows" ("id"  SERIAL , "name" VARCHAR(500) NOT NULL UNIQUE, "description" TEXT, "createdAt" TIMESTAMP WITH TIME ZONE NOT NULL, "updatedAt" TIMESTAMP WITH TIME ZONE NOT NULL, PRIMARY KEY ("id"));
CREATE INDEX IF NOT EXISTS "shows_name" ON "shows" ("name");
CREATE INDEX IF NOT EXISTS "shows_created_at" ON "shows" ("createdAt");
CREATE TABLE IF NOT EXISTS "episodes" ("id"  SERIAL , "showId" INTEGER NOT NULL REFERENCES "shows" ("id") ON DELETE NO ACTION ON UPDATE CASCADE, "name" VARCHAR(500) NOT NULL, "spotifyUri" VARCHAR(255) UNIQUE, "description" TEXT, "createdAt" TIMESTAMP WITH TIME ZONE NOT NULL, "updatedAt" TIMESTAMP WITH TIME ZONE NOT NULL, PRIMARY KEY ("id"));
CREATE INDEX IF NOT EXISTS "episodes_show_id_name" ON "episodes" ("showId", "name");
CREATE INDEX IF NOT EXISTS "episodes_spotify_uri" ON "episodes" ("spotifyUri");
CREATE INDEX IF NOT EXISTS "episodes_name" ON "episodes" ("name");
CREATE INDEX IF NOT EXISTS "episodes_created_at" ON "episodes" ("createdAt");
CREATE TABLE IF NOT EXISTS "podcast_plays" ("id"  SERIAL , "episodeId" INTEGER NOT NULL REFERENCES "episodes" ("id") ON DELETE NO ACTION ON UPDATE CASCADE, "profileId" INTEGER REFERENCES "profiles" ("id") ON DELETE SET NULL ON UPDATE CASCADE, "timestamp" TIMESTAMP WITH TIME ZONE NOT NULL, "msPlayed" BIGINT NOT NULL, "username" VARCHAR(255), "platform" VARCHAR(255), "country" VARCHAR(2), "ipAddr" VARCHAR(255), "userAgent" VARCHAR(255), "reasonStart" VARCHAR(255), "reasonEnd" VARCHAR(255), "shuffle" BOOLEAN DEFAULT false, "skipped" BOOLEAN DEFAULT false, "offline" BOOLEAN DEFAULT false, "offlineTimestamp" TIMESTAMP WITH TIME ZONE, "incognitoMode" BOOLEAN DEFAULT false, "createdAt" TIMESTAMP WITH TIME ZONE NOT NULL, "updatedAt" TIMESTAMP WITH TIME ZONE NOT NULL, PRIMARY KEY ("id"));
CREATE INDEX IF NOT EXISTS "podcast_plays_episode_id_timestamp" ON "podcast_plays" ("episodeId", "timestamp");
CREATE INDEX IF NOT EXISTS "podcast_plays_timestamp_country" ON "podcast_plays" ("timestamp", "country");
CREATE INDEX IF NOT EXISTS "podcast_plays_timestamp_platform" ON "podcast_plays" ("timestamp", "platform");
