CREATE INDEX IF NOT EXISTS "podcast_plays_profile_id_episode_id" ON "podcast_plays" ("profileId", "episodeId");
CREATE INDEX IF NOT EXISTS "podcast_plays_timestamp" ON "podcast_plays" ("timestamp");
CREATE INDEX IF NOT EXISTS "podcast_plays_ms_played" ON "podcast_plays" ("msPlayed");
CREATE INDEX IF NOT EXISTS "podcast_plays_platform" ON "podcast_plays" ("platform");
CREATE INDEX IF NOT EXISTS "podcast_plays_country" ON "podcast_plays" ("country");
CREATE INDEX IF NOT EXISTS "podcast_plays_shuffle" ON "podcast_plays" ("shuffle");
