CREATE INDEX IF NOT EXISTS "podcast_plays_incognito_mode" ON "podcast_plays" ("incognitoMode");
CREATE INDEX IF NOT EXISTS "podcast_plays_username" ON "podcast_plays" ("username");
CREATE INDEX IF NOT EXISTS "podcast_plays_offline_timestamp" ON "podcast_plays" ("offlineTimestamp");
CREATE TABLE IF NOT EXISTS "audiobooks" ("id"  SERIAL , "name" VARCHAR(255) NOT NULL, "spotifyUri" VARCHAR(255) UNIQUE, "createdAt" TIMESTAMP WITH TIME ZONE, "updatedAt" TIMESTAMP WITH TIME ZONE, PRIMARY KEY ("id"));
